import Dashboard from "./Components/Dashboard";
import MovieList from "./Components/MovieList";
import Movies from "./Components/Movies";
import Navbar from "./Components/Navbar";

function App() {
  
  return (
    <>
      <Navbar/>
      <Dashboard>
        <Movies>
          {movieList.map((movie)=><MovieList movie={movie}/>)}
        </Movies>
      </Dashboard>
    </>
  );
}

export default App;
